mapper.select:
        SELECT * FROM (
            SELECT a.*, ROWNUM rnum FROM (
                SELECT
                    posting_idx AS postingIdx,
                    title, employer, pay,
                    pay_type AS payType,
                    location, created_date AS createdDate,
                    category, work_period AS workPeriod,
                    recruit_status AS recruitStatus,
                    work_days AS workDays,
                    start_time AS startTime,
                    end_time AS endTime,
                    deadline 
                FROM job_posting


				        sido = #{sido}


				        AND gugun = #{gugun} 

				        AND dong = #{dong} 

                ORDER BY posting_idx DESC
            ) a WHERE ROWNUM <= #{offset} + #{size}
        ) WHERE rnum > #{offset}

mapper.update:
UPDATE job_posting
SET hit_count = hit_count + 1
WHERE posting_idx = #{postingIdx}

mapper.select:
SELECT img_url
FROM job_posting_image
WHERE posting_idx = #{postingIdx}

SELECT jp.posting_idx AS postingIdx, jp.title, jp.employer, jp.pay, jp.pay_type AS payType, jp.location, jp.created_date AS createdDate, jp.category, jp.work_period AS workPeriod, jp.recruit_status AS recruitStatus, jp.work_days AS workDays, jp.start_time AS startTime, jp.end_time AS endTime, jp.deadline,
CASE WHEN js.posting_idx IS NOT NULL THEN 1 ELSE 0 END AS isScrapped
FROM job_posting jp
LEFT JOIN job_scrap js ON jp.posting_idx = js.posting_idx AND js.member_id = #{userIdx}
jp.sido = #{sido}
AND jp.gugun = #{gugun}
AND jp.dong = #{dong}
ORDER BY jp.created_date DESC
